-- WEB-5.13.1 묶음 1: 입문 u1-intro, 을/를 Learn u1-l3-learn 추가, Practice u1-l3 다시 쓰기, Unit 1 순서 다시 매김 (멱등). lesson_id 유지라 진도 기록은 그대로.
-- 생성: backend/lessons/build_curriculum.py (소스 *_learn.json, *_practice.json, curriculum.csv). 직접 고치지 말 것.
-- 적용 순서: lsn_009 뒤, 번호 순서대로. concept 위젯이 들어간 앱을 먼저 배포한다. 옛 앱은 'Unknown Step Type: concept' 을 보여 주므로 옛 앱이 쓰는 DB(운영) 금지.
-- lsn_005·006·007·009 를 다시 돌리면 순서와 내용이 되돌아가므로, 그 뒤에는 이 패치도 다시 적용한다.
BEGIN;
INSERT INTO lessons (lesson_id, unit_id, unit_title, order_num, title, description,
                     difficulty_level, estimated_minutes, is_published, content, created_at, updated_at)
VALUES ('u1-intro', 1, 'Introduce Yourself', 1, 'Learn: How Korean sentences work',
        'See how blocks on words and verbs build a Korean sentence. Only three small checks, with no score.', 1, 5, true, '{"steps": []}'::jsonb, NOW(), NOW())
ON CONFLICT (lesson_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
    estimated_minutes = EXCLUDED.estimated_minutes, is_published = EXCLUDED.is_published;
INSERT INTO lessons (lesson_id, unit_id, unit_title, order_num, title, description,
                     difficulty_level, estimated_minutes, is_published, content, created_at, updated_at)
VALUES ('u1-l3-learn', 1, 'Introduce Yourself', 4, 'Learn: 을/를',
        'Slowly learn how 을/를 marks the thing you act on. Only three small checks, with no score.', 1, 5, true, '{"steps": []}'::jsonb, NOW(), NOW())
ON CONFLICT (lesson_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
    estimated_minutes = EXCLUDED.estimated_minutes, is_published = EXCLUDED.is_published;
INSERT INTO lessons (lesson_id, unit_id, unit_title, order_num, title, description,
                     difficulty_level, estimated_minutes, is_published, content, created_at, updated_at)
VALUES ('u1-l3', 1, 'Introduce Yourself', 5, 'What do you like?',
        'Practice saying what you eat, drink and like using 을/를.', 1, 10, true, '{"steps": []}'::jsonb, NOW(), NOW())
ON CONFLICT (lesson_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
    estimated_minutes = EXCLUDED.estimated_minutes, is_published = EXCLUDED.is_published;
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Korean uses blocks", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "Korean sentences are built from blocks. 저 means I, and the block 는 marks the topic: who we're talking about.", "example": {"sentence": "저는.", "translation": "I (topic)", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "These blocks are particles", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "A block on a word is called a particle. It shows the word's job, like 를 on 커피, coffee.", "example": {"sentence": "커피를.", "translation": "coffee (the thing you act on)", "tts": true, "words": [{"parts": [{"text": "커피", "meaning": "coffee", "highlight": false}, {"text": "를", "meaning": "object", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "The verb comes last", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "빵 means bread, and 먹어요 means eat. In Korean, the verb comes last.", "example": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": false}]}, {"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": false}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I eat bread.", "sentence": "저는 빵을 [ ? ].", "options": ["커피를", "먹어요"], "answer": "먹어요", "feedback": {"correct": "Yes! The verb 먹어요 comes last.", "incorrect": "The sentence needs a verb at the end. 먹어요 is the verb."}}]}}, {"step_type": "concept", "title": "Verbs get blocks too", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "Verbs have blocks too. 먹 means eat, and the ending 어요 makes it polite.", "example": {"sentence": "먹어요.", "translation": "eat", "tts": true, "words": [{"parts": [{"text": "먹", "meaning": "eat", "highlight": false}, {"text": "어요", "meaning": "polite ending", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I eat bread.", "sentence": "저는 빵을 [ ? ].", "options": ["먹어요", "먹"], "answer": "먹어요", "feedback": {"correct": "Right! 먹 needs the ending 어요.", "incorrect": "먹 alone isn't finished. Add the ending 어요."}}]}}, {"step_type": "concept", "title": "Some blocks change shape", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "Some blocks change shape. After a vowel it's 는, and after a consonant it's 은, like 이름, name.", "example": {"sentence": "이름은.", "translation": "name (topic)", "tts": true, "words": [{"parts": [{"text": "이름", "meaning": "name", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Now build a whole sentence", "instruction": "", "content": {"character": "turtle", "mood": "cheer", "explanation": "Words get particles, and verbs get endings. Tap to build the whole sentence.", "example": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "먹", "meaning": "eat", "highlight": false}, {"text": "어요", "meaning": "polite ending", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I eat bread.", "sentence": "저는 빵 [ ? ] 먹어요.", "options": ["어요", "을"], "answer": "을", "feedback": {"correct": "Yes! 을 is a particle. It goes on the word 빵.", "incorrect": "어요 is a verb ending. A word like 빵 takes a particle."}}]}}, {"step_type": "completion", "title": "You Know the Blocks!", "instruction": "Next, meet your first particle: 은/는.", "content": {"text": "Words get particles: 저는, 빵을.\nVerbs get endings: 먹어요.\nThe verb comes last.", "highlights": ["는", "을", "어요"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u1-intro';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "A block you have seen", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "You saw 을 in your first lesson. Today you'll learn what it does.", "example": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "What 을 does", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "먹어요 needs something to eat. 을 marks that thing, which we call the object.", "example": {"sentence": "민수는 빵을 먹어요.", "translation": "Minsu eats bread.", "tts": true, "words": [{"parts": [{"text": "민수는", "meaning": "Minsu (topic)", "highlight": false}]}, {"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Yumi eats bread.", "sentence": "유미는 [ ? ] 먹어요.", "options": ["빵이에요", "빵을"], "answer": "빵을", "feedback": {"correct": "Yes! 을 marks bread, the thing she eats.", "incorrect": "이에요 means am or is. Use 을 for the thing she eats."}}]}}, {"step_type": "concept", "title": "New words: 물, 마셔요", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "물 means water, and 마셔요 means drink. Water is what you drink, so it takes 을.", "example": {"sentence": "저는 물을 마셔요.", "translation": "I drink water.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "물", "meaning": "water", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "마셔요", "meaning": "drink", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "New word: 좋아해요", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "좋아해요 means like. The thing you like also takes 을.", "example": {"sentence": "유미는 빵을 좋아해요.", "translation": "Yumi likes bread.", "tts": true, "words": [{"parts": [{"text": "유미는", "meaning": "Yumi (topic)", "highlight": false}]}, {"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "좋아해요", "meaning": "like", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Minsu drinks water.", "sentence": "민수는 [ ? ] 마셔요.", "options": ["물을", "물이에요"], "answer": "물을", "feedback": {"correct": "Right! 물 is what he drinks, so 물을.", "incorrect": "물 is what he drinks. It takes 을."}}]}}, {"step_type": "concept", "title": "Sometimes it is 를", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "커피 ends in a vowel, so the block is 를, not 을.", "example": {"sentence": "저는 커피를 마셔요.", "translation": "I drink coffee.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "커피", "meaning": "coffee", "highlight": false}, {"text": "를", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "마셔요", "meaning": "drink", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "How to choose", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "After a consonant, use 을. After a vowel, use 를, like 사과, apple.", "example": {"sentence": "민수는 사과를 먹어요.", "translation": "Minsu eats an apple.", "tts": true, "words": [{"parts": [{"text": "민수는", "meaning": "Minsu (topic)", "highlight": false}]}, {"parts": [{"text": "사과", "meaning": "apple", "highlight": false}, {"text": "를", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I like coffee.", "sentence": "저는 커피 [ ? ] 좋아해요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Great! 커피 ends in a vowel, so it takes 를.", "incorrect": "커피 ends in a vowel. After a vowel, use 를."}}]}}, {"step_type": "completion", "title": "을/를 Learned!", "instruction": "Next, practice it with the rabbit.", "content": {"text": "을 and 를 mark the thing you eat, drink or like.\nConsonant → 을 (빵을). Vowel → 를 (커피를).", "highlights": ["을", "를"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u1-l3-learn';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Quick recap", "instruction": "", "content": {"character": "rabbit", "mood": "happy", "explanation": "After a consonant, use 을. After a vowel, use 를.", "example": {"sentence": "빵을 먹어요.", "translation": "eat bread", "tts": true, "words": [{"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "intro", "title": "Vocabulary: Food and Drink", "instruction": "Tap and listen. You'll use all of these today.", "content": {"explanation": {"title": "Words for today"}, "sentences": [{"korean": "커피", "english": "Coffee", "tts": true, "chunks": [{"display": "커피", "tokens": [{"text": "커피", "meaning": "coffee"}]}]}, {"korean": "빵", "english": "Bread", "tts": true, "chunks": [{"display": "빵", "tokens": [{"text": "빵", "meaning": "bread"}]}]}, {"korean": "물", "english": "Water", "tts": true, "chunks": [{"display": "물", "tokens": [{"text": "물", "meaning": "water"}]}]}, {"korean": "사과", "english": "Apple", "tts": true, "chunks": [{"display": "사과", "tokens": [{"text": "사과", "meaning": "apple"}]}]}, {"korean": "책", "english": "Book", "tts": true, "chunks": [{"display": "책", "tokens": [{"text": "책", "meaning": "book"}]}]}, {"korean": "먹어요", "english": "Eat", "tts": true, "chunks": [{"display": "먹어요", "tokens": [{"text": "먹어요", "meaning": "eat"}]}]}, {"korean": "마셔요", "english": "Drink", "tts": true, "chunks": [{"display": "마셔요", "tokens": [{"text": "마셔요", "meaning": "drink"}]}]}, {"korean": "좋아해요", "english": "Like", "tts": true, "chunks": [{"display": "좋아해요", "tokens": [{"text": "좋아해요", "meaning": "like"}]}]}, {"korean": "뭐", "english": "What", "tts": true, "chunks": [{"display": "뭐", "tokens": [{"text": "뭐", "meaning": "what"}]}]}]}}, {"step_type": "practice", "title": "Round 1: Spot the object", "instruction": "을 and 를 mark the thing you eat, drink or like.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I eat bread.", "sentence": "저는 [ ? ] 먹어요.", "options": ["빵이에요", "빵을"], "answer": "빵을", "feedback": {"correct": "Correct! Bread is what you eat, so 빵을."}}, {"type": "fill_blank", "instruction": "I drink water.", "sentence": "저는 [ ? ] 마셔요.", "options": ["물을", "물이에요"], "answer": "물을", "feedback": {"correct": "Right! Water is what you drink, so 물을."}}, {"type": "fill_blank", "instruction": "Minsu likes coffee.", "sentence": "민수는 [ ? ] 좋아해요.", "options": ["커피예요", "커피를"], "answer": "커피를", "feedback": {"correct": "Great! Coffee is what he likes, so 커피를."}}, {"type": "fill_blank", "instruction": "Yumi eats an apple.", "sentence": "유미는 [ ? ] 먹어요.", "options": ["사과를", "사과예요"], "answer": "사과를", "feedback": {"correct": "Perfect! An apple is what she eats, so 사과를."}}, {"type": "fill_blank", "instruction": "I like books.", "sentence": "저는 [ ? ] 좋아해요.", "options": ["책이에요", "책을"], "answer": "책을", "feedback": {"correct": "Correct! Books are what you like, so 책을."}}]}}, {"step_type": "practice", "title": "Round 2: 을 or 를?", "instruction": "Look at the last sound of the word.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I eat bread.", "sentence": "저는 빵 [ ? ] 먹어요.", "options": ["을", "를"], "answer": "을", "feedback": {"correct": "Correct! 빵 ends in a consonant, so it takes 을."}}, {"type": "fill_blank", "instruction": "I drink coffee.", "sentence": "저는 커피 [ ? ] 마셔요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Right! 커피 ends in a vowel, so it takes 를."}}, {"type": "fill_blank", "instruction": "Minsu drinks water.", "sentence": "민수는 물 [ ? ] 마셔요.", "options": ["를", "을"], "answer": "을", "feedback": {"correct": "Great! 물 ends in a consonant, so it takes 을."}}, {"type": "fill_blank", "instruction": "Yumi likes apples.", "sentence": "유미는 사과 [ ? ] 좋아해요.", "options": ["를", "을"], "answer": "를", "feedback": {"correct": "Perfect! 사과 ends in a vowel, so it takes 를."}}, {"type": "fill_blank", "instruction": "I like books.", "sentence": "저는 책 [ ? ] 좋아해요.", "options": ["을", "를"], "answer": "을", "feedback": {"correct": "Correct! 책 ends in a consonant, so it takes 을."}}, {"type": "fill_blank", "instruction": "Minsu likes bread.", "sentence": "민수는 빵 [ ? ] 좋아해요.", "options": ["를", "을"], "answer": "을", "feedback": {"correct": "Right! 빵 ends in a consonant, so it takes 을."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"I eat bread.\" Split 을/를. 빵 ends in a consonant, so use 을.", "contentObj": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["빵을"], "correct_turtle": ["빵", "을"], "turtle_explanation": "'을' marks the object. After a vowel use 를, after a consonant use 을."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["먹어요"], "correct_turtle": ["먹어요"], "turtle_explanation": "Keep '먹어요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "저는", "mode": "turtle"}, {"id": "o2", "text": "을", "mode": "turtle"}, {"id": "o3", "text": "빵을", "mode": "rabbit"}, {"id": "o4", "text": "저는", "mode": "rabbit"}, {"id": "o5", "text": "먹어요", "mode": "turtle"}, {"id": "o6", "text": "빵를", "mode": "rabbit"}, {"id": "o7", "text": "빵", "mode": "turtle"}, {"id": "o8", "text": "를", "mode": "turtle"}, {"id": "o9", "text": "먹어요", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"I drink coffee.\" Split 을/를 from the word.", "contentObj": {"sentence": "저는 커피를 마셔요.", "translation": "I drink coffee.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["커피를"], "correct_turtle": ["커피", "를"], "turtle_explanation": "'를' marks the object. After a vowel use 를, after a consonant use 을."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["마셔요"], "correct_turtle": ["마셔요"], "turtle_explanation": "Keep '마셔요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "커피를", "mode": "rabbit"}, {"id": "o2", "text": "을", "mode": "turtle"}, {"id": "o3", "text": "저는", "mode": "rabbit"}, {"id": "o4", "text": "저는", "mode": "turtle"}, {"id": "o5", "text": "를", "mode": "turtle"}, {"id": "o6", "text": "커피을", "mode": "rabbit"}, {"id": "o7", "text": "커피", "mode": "turtle"}, {"id": "o8", "text": "마셔요", "mode": "turtle"}, {"id": "o9", "text": "마셔요", "mode": "rabbit"}]}}, {"step_type": "intro", "title": "Conversation", "instruction": "Take a break and listen. You know these words now.", "content": {"explanation": {"title": "What do you like?"}, "sentences": [{"korean": "민수: 유미 씨, 뭐를 좋아해요?", "english": "Minsu: Yumi, what do you like?", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "유미", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}]}, {"display": "씨,", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}]}, {"display": "뭐를", "tokens": [{"text": "뭐", "meaning": "what"}, {"text": "를", "meaning": "object marker"}]}, {"display": "좋아해요?", "tokens": [{"text": "좋아하", "meaning": "like"}, {"text": "어요", "meaning": "polite ending"}]}]}, {"korean": "유미: 저는 커피를 좋아해요.", "english": "Yumi: I like coffee.", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "커피를", "tokens": [{"text": "커피", "meaning": "coffee"}, {"text": "를", "meaning": "object marker"}]}, {"display": "좋아해요.", "tokens": [{"text": "좋아하", "meaning": "like"}, {"text": "어